<script setup>
import { onBeforeUnmount, ref } from 'vue';

const props = defineProps({ payload: { type: String, required: true } });
const state = JSON.parse(props.payload);
const category = state.category || {};
const form = ref({ ...(state.old || {}) });
const errors = state.errors || {};
const preview = ref(null);
const fileName = ref('No file chosen');
const currentUrl = category.image || null;
const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
let objectUrl;

function chooseImage(event) {
    const file = event.target.files?.[0];
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    objectUrl = null;
    preview.value = null;
    fileName.value = file?.name || (state.view === 'edit' ? 'No file chosen' : 'JPG, PNG or WEBP');
    if (!file) return;
    if (!file.type.startsWith('image/')) {
        fileName.value = 'Please select an image file';
        event.target.value = '';
        return;
    }
    objectUrl = URL.createObjectURL(file);
    preview.value = objectUrl;
}

function removeCategory(url) {
    const submit = () => {
        const formElement = document.createElement('form');
        formElement.method = 'POST'; formElement.action = url;
        const token = document.createElement('input'); token.type = 'hidden'; token.name = '_token'; token.value = csrf;
        const method = document.createElement('input'); method.type = 'hidden'; method.name = '_method'; method.value = 'DELETE';
        formElement.append(token, method); document.body.append(formElement); formElement.submit();
    };
    if (window.Swal) window.Swal.fire({ title: 'Delete category?', text: 'This action cannot be undone.', icon: 'warning', showCancelButton: true, confirmButtonText: 'Delete', cancelButtonText: 'Cancel', reverseButtons: true }).then((result) => { if (result.isConfirmed) submit(); });
    else if (window.confirm('Delete this category?')) submit();
}

onBeforeUnmount(() => { if (objectUrl) URL.revokeObjectURL(objectUrl); });
</script>

<template>
    <div class="dashboard-section categories-page">
        <template v-if="state.view === 'index'">
            <section class="categories-hero"><div class="categories-hero-content"><span class="categories-hero-badge"><i class="bi bi-tags"></i> Marketplace Library</span><h1>Categories, beautifully organised.</h1><p>Create, organise and manage the categories used across the SecondBook marketplace.</p></div><div class="categories-hero-mark" aria-hidden="true"><i class="bi bi-tags"></i></div></section>
            <div v-if="state.success" class="category-alert category-alert-success"><i class="bi bi-check-circle-fill"></i><span>{{ state.success }}</span></div><div v-if="state.error" class="alert alert-danger">{{ state.error }}</div>
            <section class="categories-stats"><div v-for="item in [{label:'Total Categories',value:state.stats.total,color:'stat-blue',icon:'bi-tags'},{label:'Active',value:state.stats.active,color:'stat-green',icon:'bi-check-circle'},{label:'Inactive',value:state.stats.inactive,color:'stat-orange',icon:'bi-pause-circle'},{label:'Used by Books',value:state.stats.with_books,color:'stat-purple',icon:'bi-book'}]" :key="item.label" class="category-stat-card" :class="item.color"><div class="category-stat-content"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div><div class="category-stat-icon"><i class="bi" :class="item.icon"></i></div></div></section>
            <section class="dashboard-panel categories-panel"><div class="categories-panel-header"><div class="categories-heading-content"><span class="eyebrow">Category Directory</span><h5>All Categories</h5><p>Search, filter and manage your marketplace categories.</p></div><div class="categories-header-action"><a :href="state.urls.create" class="categories-add-btn"><i class="bi bi-plus-lg"></i><span>Add Category</span></a></div></div>
                <form method="GET" :action="state.urls.index" class="category-filters"><div class="category-filter-search"><label for="category-search">Search</label><div class="category-search-field"><i class="bi bi-search"></i><input id="category-search" name="search" :value="state.filters.search" type="text" placeholder="Category name, slug or description..." autocomplete="off"></div></div><div class="category-filter-group"><label for="category-status">Status</label><select id="category-status" name="status" class="category-filter-select"><option value="">All Status</option><option value="1" :selected="state.filters.status === '1'">Active</option><option value="0" :selected="state.filters.status === '0'">Inactive</option></select></div><div class="category-filter-actions"><button type="submit" class="category-filter-btn"><i class="bi bi-funnel"></i><span>Filter</span></button><a v-if="state.filters.search || state.filters.status !== ''" :href="state.urls.index" class="category-clear-filter"><i class="bi bi-x-lg"></i><span>Reset</span></a></div></form>
                <div class="categories-list-header"><div class="categories-list-heading"><span class="eyebrow">Category Management</span><h5>Category List</h5><p>{{ state.stats.total }} {{ state.stats.total === 1 ? 'category' : 'categories' }} available in the marketplace.</p></div><div class="categories-count-badge"><i class="bi bi-collection"></i><span>{{ state.stats.total }}</span></div></div>
                <div class="categories-table-wrap"><table class="categories-table"><thead><tr><th class="categories-col-id">ID</th><th class="categories-col-category">Category</th><th class="categories-col-slug">Slug</th><th class="categories-col-description">Description</th><th class="categories-col-books">Books</th><th class="categories-col-status">Status</th><th class="categories-col-date">Created</th><th class="categories-col-actions">Actions</th></tr></thead><tbody>
                    <tr v-for="item in state.categories" :key="item.id"><td><span class="category-id">#{{ item.id }}</span></td><td><div class="category-item-cell"><img v-if="item.image" :src="item.image" :alt="item.name" class="category-image" loading="lazy"><div v-else class="category-image-placeholder"><i class="bi bi-tags"></i></div><div class="category-item-info"><strong :title="item.name">{{ item.name }}</strong><small>Category #{{ item.id }}</small></div></div></td><td><span class="category-slug" :title="item.slug">{{ item.slug }}</span></td><td><div class="category-description">{{ item.description ? (item.description.length > 65 ? `${item.description.slice(0,62)}...` : item.description) : '—' }}</div></td><td><span class="category-book-count"><i class="bi bi-book"></i>{{ item.books_count }}</span></td><td><span class="category-status-pill" :class="item.status ? 'category-status-active' : 'category-status-inactive'"><i class="bi bi-circle-fill"></i>{{ item.status ? 'Active' : 'Inactive' }}</span></td><td><span class="category-date">{{ item.created }}</span></td><td><div class="category-actions"><a :href="item.show_url" class="category-action-btn category-action-view" title="View Category"><i class="bi bi-eye"></i></a><form :action="item.status_url" method="POST"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><button type="submit" class="category-action-btn" :class="item.status ? 'category-action-warning' : 'category-action-success'" :title="item.status ? 'Deactivate' : 'Activate'"><i class="bi" :class="item.status ? 'bi-pause-circle' : 'bi-check-circle'"></i></button></form><a :href="item.edit_url" class="category-action-btn category-action-edit" title="Edit Category"><i class="bi bi-pencil"></i></a><button type="button" class="category-action-btn category-action-delete" title="Delete Category" @click="removeCategory(item.delete_url)"><i class="bi bi-trash3"></i></button></div></td></tr>
                    <tr v-if="!state.categories.length"><td colspan="8"><div class="categories-empty-state"><div class="categories-empty-icon"><i class="bi bi-tags"></i></div><h6>No categories found</h6><p>There are no categories matching your current filters.</p><a :href="state.urls.create" class="categories-empty-btn"><i class="bi bi-plus-lg"></i>Add Category</a></div></td></tr>
                </tbody></table></div>
                <div v-if="state.pagination.last_page > 1" class="categories-pagination"><div class="categories-pagination-info">Showing <strong>{{ state.pagination.first }}</strong> to <strong>{{ state.pagination.last }}</strong> of <strong>{{ state.pagination.total }}</strong> categories</div><nav class="categories-pagination-pages" aria-label="Categories pagination"><a class="categories-pager-btn" :class="{disabled:!state.pagination.previous}" :href="state.pagination.previous || undefined"><i class="bi bi-chevron-left"></i></a><a v-for="(url,page) in state.pagination.pages" :key="page" :href="url" class="categories-pager-btn" :class="{active:Number(page) === Number(state.pagination.current)}">{{ page }}</a><a class="categories-pager-btn" :class="{disabled:!state.pagination.next}" :href="state.pagination.next || undefined"><i class="bi bi-chevron-right"></i></a></nav></div>
            </section>
        </template>

        <template v-else-if="state.view === 'create' || state.view === 'edit'">
            <section class="categories-hero"><div class="categories-hero-content"><span class="categories-hero-badge"><i class="bi bi-tags"></i>{{ state.view === 'create' ? 'New Category' : 'Category Management' }}</span><h1>{{ state.view === 'create' ? 'Create a marketplace category.' : 'Update category information.' }}</h1><p>{{ state.view === 'create' ? 'Create and organise categories used across SecondBook.' : 'Update category information, description, image and status.' }}</p></div><div class="categories-hero-mark"><i class="bi bi-tags"></i></div></section>
            <div v-if="Object.keys(errors).length" class="alert alert-danger category-form-alert"><strong>Please fix the following errors:</strong><ul class="mb-0"><template v-for="(messages,key) in errors" :key="key"><li v-for="message in messages" :key="message">{{ message }}</li></template></ul></div>
            <form :action="state.view === 'create' ? state.urls.store : state.urls.update" method="POST" enctype="multipart/form-data"><input type="hidden" name="_token" :value="csrf"><input v-if="state.view === 'edit'" type="hidden" name="_method" value="PUT">
                <div class="category-form-section"><div class="category-section-heading"><span class="category-section-icon"><i class="bi bi-tags"></i></span><span>Basic Information</span></div><div class="category-form-grid"><div class="category-field category-field-full"><label for="category-name">Category Name <span class="category-required">*</span></label><input id="category-name" name="name" class="category-input" :class="{'is-invalid':errors.name}" :value="form.name" placeholder="Enter category name" required><span v-for="error in errors.name" :key="error" class="category-field-error">{{ error }}</span></div><div class="category-field category-field-full"><label for="category-slug">Slug</label><input id="category-slug" name="slug" class="category-input" :class="{'is-invalid':errors.slug}" :value="form.slug" placeholder="example-category"><span class="category-field-hint">Leave empty if the slug is generated automatically.</span><span v-for="error in errors.slug" :key="error" class="category-field-error">{{ error }}</span></div><div class="category-field category-field-full"><label for="category-description">Description</label><textarea id="category-description" name="description" rows="6" class="category-input category-textarea" :class="{'is-invalid':errors.description}" :value="form.description" placeholder="Write a short description for this category..."></textarea><span v-for="error in errors.description" :key="error" class="category-field-error">{{ error }}</span></div></div></div>
                <div class="category-form-section"><div class="category-section-heading"><span class="category-section-icon"><i class="bi bi-image"></i></span><span>Category Image</span></div><div class="category-image-preview"><img v-if="preview || currentUrl" :src="preview || currentUrl" alt="Category image preview" class="category-preview-image"><div v-else class="category-image-placeholder"><i class="bi bi-image"></i><span>No image selected</span></div></div><div class="category-file-upload"><input id="category-image" type="file" name="image" class="category-file-native" accept="image/jpeg,image/png,image/webp" @change="chooseImage"><label for="category-image" class="category-file-label"><span class="category-file-icon"><i class="bi bi-cloud-arrow-up"></i></span><span class="category-file-content"><span class="category-file-title">{{ state.view === 'edit' ? 'Replace Image' : 'Upload image' }}</span><span class="category-file-name">{{ fileName }}</span></span><span class="category-file-button">Browse</span></label></div><span v-for="error in errors.image" :key="error" class="category-field-error">{{ error }}</span><span class="category-field-hint category-image-hint">Recommended: square image for consistent category cards.</span></div>
                <div class="category-form-section"><div class="category-section-heading"><span class="category-section-icon"><i class="bi bi-toggle-on"></i></span><span>Category Status</span></div><div class="category-status-setting"><label class="category-switch"><input type="checkbox" name="status" value="1" :checked="['1',1,true].includes(form.status)"><span class="category-switch-slider"></span></label><div class="category-status-copy"><label>Active category</label><p>Active categories can be used and displayed across the marketplace.</p></div></div></div>
                <div class="category-form-actions"><button type="submit" class="categories-add-btn"><i class="bi bi-check-circle"></i>{{ state.view === 'create' ? 'Save category' : 'Update Category' }}</button><a :href="state.urls.index" class="category-clear-filter"><i class="bi bi-x-lg"></i>Cancel</a></div>
            </form>
        </template>

        <template v-else>
            <section class="categories-hero"><div class="categories-hero-content"><span class="categories-hero-badge"><i class="bi bi-tags"></i>Category details</span><h1>{{ category.name || 'Untitled category' }}</h1><p>Full information about this category, including its description, book count, status and category image.</p></div><div class="categories-hero-mark"><i class="bi bi-tags"></i></div></section>
            <section class="categories-stats"><div v-for="item in [{label:'Category ID',value:`#${category.id}`,color:'stat-blue',icon:'bi-hash'},{label:'Books',value:category.books_count,color:'stat-green',icon:'bi-book'},{label:'Status',value:category.status?'Active':'Inactive',color:'stat-orange',icon:'bi-toggle-on'},{label:'Created',value:category.created,color:'stat-purple',icon:'bi-calendar3'}]" :key="item.label" class="category-stat-card" :class="item.color"><div class="category-stat-content"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div><div class="category-stat-icon"><i class="bi" :class="item.icon"></i></div></div></section>
            <section class="categories-panel"><div class="categories-panel-header"><div class="categories-heading-content"><span class="eyebrow">Category information</span><h5>{{ category.name }}</h5><p>Everything SecondBook knows about this category.</p></div><div class="category-actions"><a :href="state.urls.index" class="category-clear-filter"><i class="bi bi-arrow-left"></i> Back to categories</a><a :href="state.urls.edit" class="categories-add-btn"><i class="bi bi-pencil"></i>Edit Category</a></div></div>
                <div class="categories-table-wrap"><table class="categories-table"><thead><tr><th>Image</th><th>Category</th><th>Slug</th><th>Books</th><th>Status</th><th>Created</th></tr></thead><tbody><tr><td><img v-if="category.image" :src="category.image" :alt="category.name" class="category-image"><div v-else class="category-image-placeholder"><i class="bi bi-tags"></i></div></td><td><div class="category-item-info"><strong>{{ category.name }}</strong><small>Category #{{ category.id }}</small></div></td><td><span class="category-slug">{{ category.slug || '—' }}</span></td><td><span class="category-book-count"><i class="bi bi-book"></i>{{ category.books_count }}</span></td><td><span class="category-status-pill" :class="category.status?'category-status-active':'category-status-inactive'"><i class="bi bi-circle-fill"></i>{{ category.status?'Active':'Inactive' }}</span></td><td><span class="category-date">{{ category.created }}</span></td></tr></tbody></table></div>
                <div class="categories-panel-header"><div class="categories-heading-content"><span class="eyebrow">Category details</span><h5>Basic information</h5><p>Core information and metadata for this category.</p></div></div><div class="category-form-grid"><div class="category-field"><label>Category ID</label><div class="category-input">#{{ category.id }}</div></div><div class="category-field"><label>Category Name</label><div class="category-input">{{ category.name || '—' }}</div></div><div class="category-field"><label>Slug</label><div class="category-input">{{ category.slug || '—' }}</div></div><div class="category-field"><label>Book Count</label><div class="category-input">{{ category.books_count }}</div></div><div class="category-field"><label>Status</label><span class="category-status-pill" :class="category.status?'category-status-active':'category-status-inactive'">{{ category.status?'Active':'Inactive' }}</span></div><div class="category-field"><label>Created Date</label><div class="category-input">{{ category.created_full }}</div></div><div class="category-field"><label>Updated Date</label><div class="category-input">{{ category.updated_full }}</div></div><div class="category-field"><label>Image</label><div class="category-input">{{ category.image ? 'Available' : '—' }}</div></div><div class="category-field category-field-full"><label>Description</label><div class="category-input category-textarea">{{ category.description || '—' }}</div></div></div>
                <div class="categories-panel-header"><div class="categories-heading-content"><span class="eyebrow">Category image</span><h5>Image preview</h5><p>The image currently associated with this category.</p></div></div><div class="categories-form-body"><div v-if="category.image" class="category-image-preview category-detail-image-preview"><img :src="category.image" :alt="category.name" class="category-preview-image"></div><div v-else class="category-no-image category-detail-no-image"><i class="bi bi-image"></i><span>No image uploaded</span></div></div>
            </section>
        </template>
    </div>
</template>
